// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testRegression_property() public {
        address recipient = address(0x1234);
        vm.deal(address(c), 1 ether);
        uint256 balanceBefore = address(c).balance;
        vm.prank(address(this));
        c.withdrawAll(recipient);
        uint256 balanceAfter = address(c).balance;
        assertEq(balanceAfter, 0);
    }
}
